const BASE = 'https://api.themoviedb.org/3';
const IMG = 'https://image.tmdb.org/t/p';

export const posterUrl = (path: string | null, size = 'w342') =>
  path ? `${IMG}/${size}${path}` : '';
export const backdropUrl = (path: string | null, size = 'w1280') =>
  path ? `${IMG}/${size}${path}` : '';
export const logoUrl = (path: string | null, size = 'w92') =>
  path ? `${IMG}/${size}${path}` : '';
export const profileUrl = (path: string | null, size = 'w185') =>
  path ? `${IMG}/${size}${path}` : '';

import { filterMediaByAge } from '@atlantis/shared';
import type { AgeMode, AgeFilterable } from '@atlantis/shared';

/** Module-level age mode. Set by `apps/movies/src/App.tsx` from `profile.ageMode`.
 *  Every `get()` call derives `include_adult` from this, and every exported
 *  fetcher pipes results through `filterByAge()` (which delegates to shared's
 *  `filterMediaByAge`). Policy for kid/teen/adult lives in `@atlantis/shared` —
 *  see `docs/profile.md` for the exact rules. */
let _ageMode: AgeMode = 'adult';
export function setAgeMode(mode: AgeMode): void { _ageMode = mode; }

/** Apply the current age mode to any list of media items — thin wrapper over
 *  `filterMediaByAge` from `@atlantis/shared` using this module's `_ageMode`. */
export function filterByAge<T extends AgeFilterable>(items: T[]): T[] {
  return filterMediaByAge(items, _ageMode);
}

async function get(apiKey: string, path: string, params: Record<string, string> = {}) {
  const url = new URL(`${BASE}${path}`);
  url.searchParams.set('api_key', apiKey);
  url.searchParams.set('language', 'en-US');
  if (params['include_adult'] === undefined) {
    url.searchParams.set('include_adult', String(_ageMode === 'adult'));
  }
  for (const [k, v] of Object.entries(params)) url.searchParams.set(k, v);
  const res = await fetch(url.toString());
  if (!res.ok) throw new Error(`TMDB ${res.status}`);
  return res.json();
}

