// Netflix provider ID in TMDB
const NETFLIX_PROVIDER_ID = 8;

/**
 * Queries the iTunes Search API to get the exact Apple TV deep-link URL
 * for a title. The returned URL (e.g. https://itunes.apple.com/us/movie/…)
 * automatically opens the TV app on macOS / iOS to the specific asset.
 * Falls back to Apple TV search if nothing is found.
 */
export async function fetchAppleTVUrl(
  title: string,
  mediaType: MediaType,
  year?: string,
): Promise<string> {
  try {
    const media  = mediaType === 'movie' ? 'movie'  : 'tvShow';
    const entity = mediaType === 'movie' ? 'movie'  : 'tvSeason';
    const res = await fetch(
      `https://itunes.apple.com/search?term=${encodeURIComponent(title)}&country=us&media=${media}&entity=${entity}&limit=5`,
    );
    if (!res.ok) throw new Error('iTunes API error');
    const data = await res.json();
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const results: any[] = data.results ?? [];
    if (!results.length) throw new Error('no results');

    // Prefer an exact year match when available
    let best = results[0];
    if (year) {
      const y = parseInt(year, 10);
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const match = results.find((r: any) => String(r.releaseDate ?? '').startsWith(String(y)));
      if (match) best = match;
    }

    const url: string = best.trackViewUrl ?? best.collectionViewUrl ?? '';
    if (!url) throw new Error('no url');
    return url;
  } catch {
    return `https://tv.apple.com/search?term=${encodeURIComponent(title)}`;
  }
}

// Providers that integrate with the Apple TV app — clicking opens Apple TV
// which then launches the correct streaming app for playback.
// Disney+, Amazon Prime, Max/HBO Max, and Peacock all channel through Apple TV.
const APPLE_TV_PROVIDERS = new Set([337, 9, 350, 384, 1899, 386]);

/** Whether this provider opens via Apple TV rather than its own website. */
export function opensViaAppleTV(providerId: number): boolean {
  return APPLE_TV_PROVIDERS.has(providerId);
}

// Providers that need their own direct URL (not in Apple TV or better standalone).
const DIRECT_PROVIDER_URLS: Record<number, (title: string) => string> = {
  8:   (t) => `https://www.netflix.com/search?q=${encodeURIComponent(t)}`,          // Netflix
  15:  (t) => `https://www.hulu.com/search?q=${encodeURIComponent(t)}`,             // Hulu
  531: (t) => `https://www.paramountplus.com/search/?q=${encodeURIComponent(t)}`,   // Paramount+
  283: (t) => `https://www.crunchyroll.com/search?q=${encodeURIComponent(t)}`,      // Crunchyroll
  11:  (t) => `https://mubi.com/en/search?query=${encodeURIComponent(t)}`,          // MUBI
};

/**
 * Returns the watch URL for a provider.
 * - Netflix, Hulu, Paramount+, Crunchyroll, MUBI → direct service link
 * - Disney+, Prime, Max, Peacock, Apple TV+ → Apple TV deep link
 *   (Apple TV aggregates these and hands off to the native app for playback)
 * - Unknown providers → Apple TV fallback
 */
export function getWatchUrl(
  provider: WatchProvider,
  title: string,
  appleTVUrl?: string | null,
): string {
  const direct = DIRECT_PROVIDER_URLS[provider.provider_id];
  if (direct) return direct(title);
  if (APPLE_TV_PROVIDERS.has(provider.provider_id)) {
    return appleTVUrl ?? `https://tv.apple.com/search?term=${encodeURIComponent(title)}`;
  }
  return appleTVUrl ?? `https://tv.apple.com/search?term=${encodeURIComponent(title)}`;
}

export function mediaTitle(item: MediaItem | MediaDetail): string {
  return item.title ?? item.name ?? 'Unknown';
}

export function mediaYear(item: MediaItem | MediaDetail): string {
  const date = item.release_date ?? (item as MediaItem).first_air_date ?? '';
  return date.slice(0, 4);
}

// ── Accumulative discover filter ───────────────────────────────────────────────

export interface DiscoverFilters {
  genres: number[];        // genre IDs, OR-combined
  providerIds: number[];   // provider IDs, OR-combined
  decades: string[];       // e.g. ['2020s', '2010s'] — combined into min/max year range
}

/** Map decade label → year range */
const DECADE_RANGES: Record<string, [number, number]> = {
  '2020s': [2020, 2029],
  '2010s': [2010, 2019],
  '2000s': [2000, 2009],
  '1990s': [1990, 1999],
  '1980s': [1980, 1989],
  'Classic': [1900, 1979],
};

export const DECADES = Object.keys(DECADE_RANGES);

function decadesToYearRange(decades: string[]): { from?: number; to?: number } {
  if (!decades.length) return {};
  const ranges = decades.map((d) => DECADE_RANGES[d]).filter(Boolean);
  const from = Math.min(...ranges.map(([f]) => f));
  const to   = Math.max(...ranges.map(([, t]) => t));
  return { from, to };
}

export async function discoverFiltered(
  apiKey: string,
  mediaType: MediaType | 'all',
  filters: DiscoverFilters,
): Promise<MediaItem[]> {
  const params: Record<string, string> = { sort_by: 'popularity.desc' };

  if (filters.genres.length) {
    params.with_genres = filters.genres.join('|'); // OR logic: any of these genres
  }
  if (filters.providerIds.length) {
    params.with_watch_providers = filters.providerIds.join('|');
    params.watch_region = 'US';
  }

  const { from, to } = decadesToYearRange(filters.decades);
  if (from) {
    params['primary_release_date.gte'] = `${from}-01-01`;
    params['first_air_date.gte']       = `${from}-01-01`;
  }
  if (to) {
    params['primary_release_date.lte'] = `${to}-12-31`;
    params['first_air_date.lte']       = `${to}-12-31`;
  }

  if (mediaType === 'all') {
    const [m, t] = await Promise.all([
      get(apiKey, '/discover/movie', params),
      get(apiKey, '/discover/tv', params),
    ]);
    const merged = [
      ...(m.results as MediaItem[]).map((i) => ({ ...i, media_type: 'movie' as MediaType })),
      ...(t.results as MediaItem[]).map((i) => ({ ...i, media_type: 'tv'    as MediaType })),
    ].sort((a, b) => (b.popularity ?? 0) - (a.popularity ?? 0) || b.vote_average - a.vote_average);
    return filterByAge(merged);
  }

  const data = await get(apiKey, `/discover/${mediaType}`, params);
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: mediaType as MediaType })));
}

/** In kid mode, every "browsey" endpoint redirects to a Family-filtered
 *  discover call — trending/popular/top-rated aren't guaranteed to include
 *  enough Family content to fill a row, so we query Family directly and
 *  sort by popularity to keep the "what's hot" feel. */
const KID_DISCOVER_PARAMS = {
  with_genres: '10751', // Family
  sort_by: 'popularity.desc',
  'vote_count.gte': '50',
};

export async function getTrending(apiKey: string): Promise<MediaItem[]> {
  if (_ageMode === 'kid') {
    const [m, t] = await Promise.all([
      get(apiKey, '/discover/movie', KID_DISCOVER_PARAMS),
      get(apiKey, '/discover/tv',    KID_DISCOVER_PARAMS),
    ]);
    const merged = [
      ...(m.results as MediaItem[]).map((i) => ({ ...i, media_type: 'movie' as MediaType })),
      ...(t.results as MediaItem[]).map((i) => ({ ...i, media_type: 'tv'    as MediaType })),
    ].sort((a, b) => (b.popularity ?? 0) - (a.popularity ?? 0));
    return filterByAge(merged);
  }
  const data = await get(apiKey, '/trending/all/week');
  return filterByAge(
    (data.results as MediaItem[]).filter(
      (i) => i.media_type === 'movie' || i.media_type === 'tv',
    ),
  );
}

export async function getPopularMovies(apiKey: string): Promise<MediaItem[]> {
  const path = _ageMode === 'kid' ? '/discover/movie' : '/movie/popular';
  const params = _ageMode === 'kid' ? KID_DISCOVER_PARAMS : {};
  const data = await get(apiKey, path, params);
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: 'movie' as MediaType })));
}

export async function getPopularTv(apiKey: string): Promise<MediaItem[]> {
  const path = _ageMode === 'kid' ? '/discover/tv' : '/tv/popular';
  const params = _ageMode === 'kid' ? KID_DISCOVER_PARAMS : {};
  const data = await get(apiKey, path, params);
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: 'tv' as MediaType })));
}

export async function getTopRated(apiKey: string, type: MediaType): Promise<MediaItem[]> {
  const path = _ageMode === 'kid' ? `/discover/${type}` : `/${type}/top_rated`;
  const params = _ageMode === 'kid'
    ? { ...KID_DISCOVER_PARAMS, sort_by: 'vote_average.desc', 'vote_count.gte': '500' }
    : {};
  const data = await get(apiKey, path, params);
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: type })));
}

export async function getDocumentaries(apiKey: string): Promise<MediaItem[]> {
  const [movies, tv] = await Promise.all([
    get(apiKey, '/discover/movie', { with_genres: '99', sort_by: 'popularity.desc' }),
    get(apiKey, '/discover/tv', { with_genres: '99', sort_by: 'popularity.desc' }),
  ]);
  const merged = [
    ...(movies.results as MediaItem[]).map((i) => ({ ...i, media_type: 'movie' as MediaType })),
    ...(tv.results as MediaItem[]).map((i) => ({ ...i, media_type: 'tv' as MediaType })),
  ].sort((a, b) => b.vote_average - a.vote_average);
  return filterByAge(merged);
}

export async function getByYear(
  apiKey: string,
  year: number,
  type: MediaType,
): Promise<MediaItem[]> {
  const params: Record<string, string> =
    type === 'movie'
      ? { primary_release_year: String(year), sort_by: 'popularity.desc' }
      : { first_air_date_year: String(year), sort_by: 'popularity.desc' };
  const data = await get(apiKey, `/discover/${type}`, params);
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: type })));
}

export async function getByGenre(
  apiKey: string,
  genreId: number,
  type: MediaType,
): Promise<MediaItem[]> {
  const data = await get(apiKey, `/discover/${type}`, {
    with_genres: String(genreId),
    sort_by: 'popularity.desc',
  });
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: type })));
}

export async function getByStreamingProvider(
  apiKey: string,
  providerId: number,
  type: MediaType,
  country = 'US',
): Promise<MediaItem[]> {
  const data = await get(apiKey, `/discover/${type}`, {
    with_watch_providers: String(providerId),
    watch_region: country,
    sort_by: 'popularity.desc',
  });
  return filterByAge((data.results as MediaItem[]).map((i) => ({ ...i, media_type: type })));
}

export async function search(apiKey: string, query: string): Promise<MediaItem[]> {
  // include_adult: keep 'false' even in adult mode — search is easily triggered
  // accidentally and search terms often surface adult matches unintentionally.
  const data = await get(apiKey, '/search/multi', { query, include_adult: 'false' });
  return filterByAge(
    (data.results as MediaItem[]).filter(
      (i) => i.media_type === 'movie' || i.media_type === 'tv',
    ),
  );
}

export async function getDetail(
  apiKey: string,
  type: MediaType,
  id: number,
): Promise<MediaDetail> {
  const data = await get(apiKey, `/${type}/${id}`);
  return { ...data, media_type: type };
}

export async function getVideos(
  apiKey: string,
  type: MediaType,
  id: number,
): Promise<VideoResult[]> {
  const data = await get(apiKey, `/${type}/${id}/videos`);
  return (data.results ?? []) as VideoResult[];
}

export async function getWatchProviders(
  apiKey: string,
  type: MediaType,
  id: number,
  country = 'US',
): Promise<WatchProviders> {
  const data = await get(apiKey, `/${type}/${id}/watch/providers`);
  return data.results?.[country] ?? {};
}

export async function getCredits(
  apiKey: string,
  type: MediaType,
  id: number,
): Promise<CastMember[]> {
  const data = await get(apiKey, `/${type}/${id}/credits`);
  return ((data.cast ?? []) as CastMember[])
    .sort((a, b) => a.order - b.order)
    .slice(0, 20);
}

export async function getRecommendations(
  apiKey: string,
  type: MediaType,
  id: number,
): Promise<MediaItem[]> {
  const data = await get(apiKey, `/${type}/${id}/recommendations`);
  return ((data.results ?? []) as MediaItem[])
    .filter((r) => r.poster_path)
    .map((r) => ({ ...r, media_type: r.media_type ?? type }))
    .slice(0, 15);
}

export async function getSimilar(
  apiKey: string,
  type: MediaType,
  id: number,
): Promise<MediaItem[]> {
  const data = await get(apiKey, `/${type}/${id}/similar`);
  return ((data.results ?? []) as MediaItem[])
    .filter((r) => r.poster_path)
    .map((r) => ({ ...r, media_type: r.media_type ?? type }))
    .slice(0, 15);
}
